// ---------------------------------------------------------------------
// Test infrastructure — minimal CUDA backend + cgraph runner.
// Mirrors the pattern in test-q4-0-ar16-cuda.cpp.
// ---------------------------------------------------------------------

struct cuda_runner {
    ggml_backend_t backend = nullptr;
    ggml_context * ctx     = nullptr;
    std::vector<uint8_t> buf;

    cuda_runner() {
        backend = ggml_backend_cuda_init(0, nullptr);
        if (!backend) {
            fprintf(stderr, "ggml_backend_cuda_init failed\n");
            std::exit(2);
        }
        struct ggml_init_params params = {
            /* .mem_size   = */ 16 * 1024 * 1024,
            /* .mem_buffer = */ nullptr,
            /* .no_alloc   = */ true,
        };
        ctx = ggml_init(params);
        assert(ctx != nullptr);
    }

    ~cuda_runner() {
        if (ctx)     ggml_free(ctx);
        if (backend) ggml_backend_free(backend);
    }

    // Allocate every tensor in `ctx` to `backend`, build the supplied
    // cgraph, and run it. Returns true on completion, false on failure.
    bool run(ggml_cgraph * gf) {
        ggml_backend_buffer_t buf = ggml_backend_alloc_ctx_tensors(ctx, backend);
        if (!buf) {
            fprintf(stderr, "ggml_backend_alloc_ctx_tensors failed\n");
            return false;
        }
        const auto status = ggml_backend_graph_compute(backend, gf);
        const bool ok = (status == GGML_STATUS_SUCCESS);
        ggml_backend_buffer_free(buf);
        return ok;
    }
};

// Fill a tensor with a deterministic ramp on host, copy to device.
void fill_ramp_f32(ggml_backend_t backend, ggml_tensor * t, float base) {
    const size_t n = ggml_nelements(t);
    std::vector<float> data(n);
    for (size_t i = 0; i < n; ++i) data[i] = base + (float) i;
    ggml_backend_tensor_set(t, data.data(), 0, n * sizeof(float));
}

// ---------------------------------------------------------------------
// Test 1 — GgmlConcatOperands.SrcDstDtypeUniform — POSITIVE
//
// Spec construct: contract GgmlConcatOperands @invariant SrcDstDtypeUniform
// Obligation:     contract-signature.GgmlConcatOperands.invoke
//
// Two F32 tensors of differing dim-1 length, concat'd on dim 1, must
// run to completion on CUDA. This is the in-spec case.
// ---------------------------------------------------------------------
bool test_concat_uniform_f32() {
    cuda_runner r;

    const int64_t n_embd = 32;
    const int64_t blk_a  = 5;
    const int64_t blk_b  = 3;

    ggml_tensor * a = ggml_new_tensor_2d(r.ctx, GGML_TYPE_F32, n_embd, blk_a);
    ggml_tensor * b = ggml_new_tensor_2d(r.ctx, GGML_TYPE_F32, n_embd, blk_b);
    ggml_set_name(a, "blk_a");
    ggml_set_name(b, "blk_b");

    ggml_tensor * out = ggml_concat(r.ctx, a, b, /*dim*/ 1);
    ggml_set_name(out, "out");

    ggml_cgraph * gf = ggml_new_graph(r.ctx);
    ggml_build_forward_expand(gf, out);

    fill_ramp_f32(r.backend, a, 0.0f);
    fill_ramp_f32(r.backend, b, 1000.0f);

    const bool ok = r.run(gf);
    if (!ok) {
        fprintf(stderr, "test_concat_uniform_f32: graph_compute failed\n");
        return false;
    }
    if (out->ne[1] != blk_a + blk_b) {
        fprintf(stderr, "test_concat_uniform_f32: out->ne[1]=%lld, want %lld\n",
                (long long) out->ne[1], (long long) (blk_a + blk_b));
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------
// Test 2 — GgmlConcatOperands.SrcDstDtypeUniform — NEGATIVE
//
// Spec construct: contract GgmlConcatOperands @invariant SrcDstDtypeUniform
// Obligation:     contract-signature.GgmlConcatOperands.invoke
//
// Two tensors of DIFFERENT dtype concat'd on CUDA. Documents the
// kernel-level precondition that the production crash violates.
//
// Status today: the call to ggml_concat at graph build time succeeds
// (ggml.c does not validate types), and ggml_backend_graph_compute
// then aborts the process via GGML_ASSERT in concat.cu:202. The test
// process can't recover, so it can't directly assert "abort happens";
// instead it documents the expected failure mode. Run manually via
// the standalone target to reproduce the production crash signature
// without needing the 27B model.
//
// Once the layer-level fix lands, no caller in the production code
// path issues mismatched-dtype concat, so this test's negative case
// is purely a contract guard. The kernel assert is a backstop.
//
// To run: env QNEXT_RUN_CONCAT_NEGATIVE=1 ./test-qnext-multislot-dispatch
// (default skipped to keep CI green; the abort is intentional).
// ---------------------------------------------------------------------
bool test_concat_mismatched_dtypes_aborts() {
    if (std::getenv("QNEXT_RUN_CONCAT_NEGATIVE") == nullptr) {
        printf("test_concat_mismatched_dtypes_aborts: SKIPPED (set QNEXT_RUN_CONCAT_NEGATIVE=1 to run)\n");
        return true;
    }

    cuda_runner r;

    const int64_t n_embd = 32;
    const int64_t blk_a  = 5;
    const int64_t blk_b  = 3;

    ggml_tensor * a = ggml_new_tensor_2d(r.ctx, GGML_TYPE_F32, n_embd, blk_a);
    ggml_tensor * b = ggml_new_tensor_2d(r.ctx, GGML_TYPE_F16, n_embd, blk_b);
    ggml_set_name(a, "blk_a_f32");
    ggml_set_name(b, "blk_b_f16");

    // ggml_concat does not validate at construction (ggml.c:6927-6960).
    // The result tensor takes a's type; the CUDA kernel guard at
    // concat.cu:202 catches the mismatch at execution.
    ggml_tensor * out = ggml_concat(r.ctx, a, b, /*dim*/ 1);
    ggml_set_name(out, "out_mismatched");

    ggml_cgraph * gf = ggml_new_graph(r.ctx);
    ggml_build_forward_expand(gf, out);

    fill_ramp_f32(r.backend, a, 0.0f);
    // b is F16, fill via host side then upload as raw bytes.
    {
        const size_t n = (size_t) n_embd * blk_b;
        std::vector<uint16_t> raw(n, 0);
        ggml_backend_tensor_set(b, raw.data(), 0, n * sizeof(uint16_t));
    }

    fprintf(stderr, "test_concat_mismatched_dtypes_aborts: about to run, "
            "expecting GGML_ASSERT abort in concat.cu:202\n");
    const bool ok = r.run(gf);
    // If we reach this line at all, the kernel assert did NOT fire,
    // which would itself be a contract violation (silent corruption).
    fprintf(stderr, "test_concat_mismatched_dtypes_aborts: graph_compute returned ok=%d "
            "WITHOUT aborting — this is a CONTRACT VIOLATION, the kernel "
            "guard is missing or has been weakened\n", ok ? 1 : 0);
    return false;
}

